sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        // Get flow name from request
        var requestBody = request.body.data.data;
        var flowName = requestBody.flowName;

        if (!flowName) {
            response.setStatus(400);
            response.setBody({
                success: false,
                message: "Flow name is required"
            });
            return;
        }

        // Get the flow record
        var flowGR = new GlideRecord('sys_hub_flow');
        flowGR.addQuery('name', flowName);
        flowGR.query();

        if (flowGR.next()) {
            // Set the active field to true
            flowGR.setValue('active', false);
            var updateSuccess = flowGR.update();

            if (updateSuccess) {
                response.setStatus(200);
                response.setBody({
                    success: true,
                    message: "Flow activated successfully"
                });
            } else {
                response.setStatus(500);
                response.setBody({
                    success: false,
                    message: "Failed to update flow record"
                });
            }
        } else {
            response.setStatus(404);
            response.setBody({
                success: false,
                message: "Flow not found"
            });
        }
    } catch(e) {
        gs.error("Error in Flow Activation API: " + e);
        response.setStatus(500);
        response.setBody({
            success: false,
            message: "Internal server error: " + e.toString()
        });
    }
})(request, response);
